func (this *Revolutx) fetchCurrenciesBody(ch chan AsyncResult[map[string]any], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	var request map[string]any = map[string]any{}
	var region *string = this.SafeString2(params, "region", "region", this.Options["region"])
	if region != nil {
		request["region"] = region
	}

	r := <-this.PublicGet10PublicConfigurationCurrencies(this.Extend(request, params))
	if r.Err != nil {
		panic(r.Err)
	}
	response := r.Raw
	//
	//     {
	//         "BTC": { "symbol": "BTC", "name": "Bitcoin", "scale": 8, "asset_type": "crypto", "status": "active" },
	//         "USD": { "symbol": "$", "name": "US Dollar", "scale": 2, "asset_type": "fiat", "status": "active" }
	//     }
	//
	var currencies any = this.SafeDict(response, "data", response)
	var keys []string = ObjectKeys(currencies)
	var result map[string]any = map[string]any{}
	for i := 0; i < len(keys); i++ {
		var key string = keys[i]
		var currency map[string]any = this.SafeDictMap(currencies, key, map[string]any{})
		var currencyData map[string]any = this.Extend(currency, map[string]any{
			"id": key,
		})
		var parsed map[string]any = this.ParseCurrency(currencyData)
		var code *string = this.SafeString(parsed, "code", "")
		if code != nil && *code == "" {
			continue
		}
		if code != nil {
			result[*code] = parsed
		}
	}

	ch <- AsyncResult[map[string]any]{Value: result}
	return nil
}

/**
 * @method
 * @name revolutx#parseTicker
 * @description parses a ticker from the exchange's ticker data
 * @ignore
 * @param {object} ticker the raw ticker data from the exchange
 * @param {object} [market] the market the ticker is for
 * @returns {object} a [ticker structure]{@link https://docs.ccxt.com/?id=ticker-structure}
 */
func (this *Revolutx) ParseTicker(ticker any, optionalArgs ...any) Ticker {
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var tickerSymbol *string = this.SafeString(ticker, "symbol")
	var symbol *string = this.SafeSymbol(tickerSymbol, market, "/")
	var bid *string = this.SafeString(ticker, "bid")
	var ask *string = this.SafeString(ticker, "ask")
	var last *string = this.SafeString(ticker, "last_price")
	var high *string = this.SafeString(ticker, "high_24h")
	var low *string = this.SafeString(ticker, "low_24h")
	var priceChange *string = this.SafeString(ticker, "price_change_24h")
	var baseVolume *string = this.SafeString(ticker, "volume_24h")
	var timestamp *int64 = this.SafeInteger(ticker, "timestamp")
	var open *string = nil
	if (last != nil) && (priceChange != nil) {
		open = Precise.StringSub(last, priceChange)
	}
	var percentage *float64 = nil
	if (open != nil) && (priceChange != nil) {
		var percentageString *string = Precise.StringDiv(priceChange, open, 8)
		percentage = this.ParseNumber(Precise.StringMul(percentageString, "100"))
	}
	return this.SafeTicker(map[string]any{
		"symbol":        symbol,
		"timestamp":     timestamp,
		"datetime":      this.Iso8601(timestamp),
		"high":          high,
		"low":           low,
		"bid":           bid,
		"bidVolume":     nil,
		"ask":           ask,
		"askVolume":     nil,
		"vwap":          nil,
		"open":          open,
		"close":         last,
		"last":          last,
		"previousClose": nil,
		"change":        priceChange,
		"percentage":    percentage,
		"average":       nil,
		"baseVolume":    baseVolume,
		"quoteVolume":   nil,
		"info":          ticker,
	}, market)
}

